#include <algorithm>
#include <iostream>

int main() {
    int arr[] = { 5, 6, 2, 4, 1, 3 };

    // Pointers are used as Random Access Iterators
    int* first = arr; // Decay to pointer
    int* last = arr + 6; // One past the end

    std::sort(first, last); 

    // arr[0] == 1, arr[5] == 6
    std::cout << arr[0] << std::endl;

    // O(1) random access using pointer arithmetic
    *(first + 3) = 99; 
}
